fun interface OrderStore { fun save(id: Long) }
class OrderService(private val store: OrderStore) {
    fun place(id: Long) { store.save(id) }
}

@Configuration(proxyBeanMethods = false)
class AppConfig {
    @Bean OrderStore orderStore() { return new MemoryOrderStore(); }
    @Bean OrderService orderService(OrderStore store) {
        return new OrderService(store);
    }
}

@Component
class ReportService {
    private final ObjectProvider<ReportBuffer> buffers;
    ReportService(ObjectProvider<ReportBuffer> buffers) { this.buffers = buffers; }
    String report() {
        return buffers.getObject().render();
    }
}
