@Configuration(proxyBeanMethods = false)
@Profile("local")
class LocalStoreConfig {
    @Bean OrderStore orderStore() { return new MemoryOrderStore(); }
}

@Aspect
@Component
class TimingAspect {
    @Around("execution(* example.orders.OrderService.*(..))")
    Object measure(ProceedingJoinPoint call) throws Throwable {
        long start = System.nanoTime();
        try { return call.proceed(); }
        finally { System.out.println("elapsedNs=" + (System.nanoTime() - start)); }
    }
}

@Service
class OrderService(private val store: OrderStore) {
    @Transactional
    fun place(id: Long) {
        store.save(id)
    }
}

